class Base:
    def describe(self):
        return "base"


class Middle(Base):
    def describe(self):
        return "middle then " + super().describe()


class Leaf(Middle):
    def describe(self):
        return "leaf then " + super(Middle, self).describe()

class Base:
    def parse(self, name):
        return name.strip().lower()


class Loader(Base):
    def load(self, names):
        def one(name):
            return "loaded:" + super().parse(name)

        return [one(n) for n in names]
